def minimum_dominating_subsequence(nums):
 remaining=sum(nums);chosen=[];selected=0
 for value in sorted(nums,reverse=True):
  chosen.append(value);selected+=value;remaining-=value
  if selected>remaining:return chosen
 return chosen

